on":10,"disciplinePair":["shadehand","vanguard"]},"after":{"id":"resonance.shadehand-vanguard.broken-line","name":"Broken Formation","media":{"vfxKey":"resonance.shadehand-vanguard.broken-line.vfx","iconKey":"resonance.shadehand-vanguard.broken-line.icon","audioCueKey":"resonance.shadehand-vanguard.broken-line.audio"},"ability":{"behaviors":[{"id":"broken-line","mode":"action","costs":[{"amount":8,"resource":"hp"}],"effects":[{"id":"effect-3","payload":{"type":"apply-status","stacks":1,"statusId":"challenged","recipient":"primary-unit","durationTurns":2}},{"id":"effect-4","payload":{"type":"apply-status","stacks":1,"statusId":"inspired","recipient":"actor","durationTurns":1,"potencyBasisPoints":1500}}],"cooldown":{"key":"resonance.shadehand-vanguard.broken-line","ownerTurns":3},"targeting":{"kind":"unit","shape":{"kind":"single"},"categories":["enemy"],"teamPolicy":"enemy","friendlyFire":"enemies-only","maximumRange":4,"minimumRange":1,"geometryVersion":3,"maximumSelections":1,"requiresLineOfSight":true,"maximumElevationDifference":0},"activation":"automatic","requirements":{"kind":"status-presence","present":true,"subject":"owner","statusId":"covert"},"classification":"utility","automaticTarget":{"subject":"triggering"},"requirementMode":"simple","activationLimits":["once-per-action","once-per-round"],"automaticTrigger":"enemy-turn-started"}],"schemaVersion":1},"enabled":true,"trigger":{"kind":"skill-trigger-v2","mode":"sequence","setup":{"requiredTags":["expose"],"sourceDisciplineId":"shadehand"},"trigger":{"requiredTags":["attack","melee"],"sourceDisciplineId":"vanguard"},"resultEffects":[{"type":"damage","amount":5,"recipient":"primary-unit","durationTurns":0},{"type":"apply-status","stacks":1,"statusId":"exposed","recipient":"primary-unit","durationTurns":1,"potencyBasisPoints":1200}],"aiSetupUtilityBonus":14,"aiTriggerUtilityBonus":32},"authoring":{"status":"representative","schemaVersion":2,"validationTags":["p3.5","representative","foundation-trio","expose-payoff","owner-rebalance-v5","thematic-resonance-payoff","duration-aware","owner-rebalance-v5-1","resonance-sequence-v2","setup-trigger-result","owner-clarified-resonance-matchers","owner-identity-restoration-20261019","owner-simple-requirements-20261019","owner-resonance-quality-20261022","owner-trigger-recovery-20261022"]},"flavorLine":"Broken Line carries Shadehand momentum into a Vanguard response shaped by both Disciplines.","description":"Requirement: covert [Self]. Result: challenged [Target]; inspired [Self].","contentVersion":11,"disciplinePair":["shadehand","vanguard"]}}]$owner_state$::jsonb;
 entry jsonb;
 actor uuid;
 owner_count int;
 current_definition jsonb;
 version_now int;
 top_version int;
 inserted record;
BEGIN
 SELECT COUNT(*),MIN(user_id) INTO owner_count,actor
   FROM app_private.master_panel_role_assignments
   WHERE role='game-owner' AND enabled;
 IF owner_count<>1 THEN RAISE EXCEPTION 'RESONANCE_TRIGGER_OWNER_UNVERIFIED'; END IF;
 PERFORM app_private.assert_game_owner_v1(actor);
 IF (SELECT COUNT(*) FROM app_private.combat_content_versions)<>1097
    OR (SELECT COUNT(*) FROM app_private.combat_content_publications)<>294
    OR (SELECT COUNT(*) FROM app_private.combat_content_publications WHERE content_kind='resonance')<>136
    OR EXISTS(SELECT 1 FROM app_private.combat_content_drafts)
    OR (public.read_combat_effect_timing_policy_v1()->>'version')::int<>8
    OR jsonb_array_length(rows)<>13
    OR (SELECT COUNT(DISTINCT v->>'id') FROM jsonb_array_elements(rows) v)<>13
 THEN RAISE EXCEPTION 'RESONANCE_TRIGGER_INVENTORY_CHANGED'; END IF;
 -- Verify exact old definitions for every member and preserve immutable versions.
 FOR entry IN SELECT value FROM jsonb_array_elements(rows) LOOP
   SELECT v.definition,v.content_version INTO current_definition,version_now
     FROM app_private.combat_content_publications p
     JOIN app_private.combat_content_versions v ON p.version_id=v.id
     WHERE p.content_kind='resonance' AND p.content_key=entry->>'id';
   SELECT MAX(content_version) INTO top_version FROM app_private.combat_content_versions
     WHERE content_kind='resonance' AND content_key=entry->>'id';
   IF current_definition IS DISTINCT FROM entry->'before'
      OR version_now IS DISTINCT FROM (entry->'before'->>'contentVersion')::int
      OR top_version IS DISTINCT FROM version_now
      OR (entry->'after'->>'contentVersion')::int<>version_now+1
      OR entry->'before'->>'id' IS DISTINCT FROM entry->>'id'
      OR entry->'after'->>'id' IS DISTINCT FROM entry->>'id'
   THEN RAISE EXCEPTION 'RESONANCE_TRIGGER_STALE_OR_INVALID: %',entry->>'id'; END IF;
 END LOOP;
 FOR entry IN SELECT value FROM jsonb_array_elements(rows) LOOP
   SELECT * INTO inserted FROM app_private.publish_combat_content_with_floor_v1(
     actor,entry->>'id','resonance',entry->'after',
     (entry->'before'->>'contentVersion')::int,
     (entry->'before'->>'contentVersion')::int
   );
   IF inserted.definition IS DISTINCT FROM entry->'after'
      OR inserted.content_version IS DISTINCT FROM (entry->'after'->>'contentVersion')::int
   THEN RAISE EXCEPTION 'RESONANCE_TRIGGER_INSERT_MISMATCH: %',entry->>'id'; END IF;
 END LOOP;
 -- Verify every complete published JSONB definition, not just changed trigger fields.
 IF EXISTS(
   SELECT 1 FROM jsonb_array_elements(rows) AS wanted(item)
   LEFT JOIN app_private.combat_content_publications p ON p.content_key=wanted.item->>'id' AND p.content_kind='resonance'
   LEFT JOIN app_private.combat_content_versions v ON v.id=p.version_id
   WHERE v.definition IS DISTINCT FROM wanted.item->'after'
 ) OR (SELECT COUNT(*) FROM app_private.combat_content_versions)<>1110
 THEN RAISE EXCEPTION 'RESONANCE_TRIGGER_FINAL_READBACK_FAILED'; END IF;
END
$owner_status$;
COMMIT;
